requestPayload.requestBody:
{ 
    "jobRequisitionId": "${reqId}", 
    "candidate": { 
        "email": inputData.candidate.email, 
        "firstName": inputData.candidate.firstName, 
        "lastName": inputData.candidate.lastName, 
        "contactDetails": { 
            "PhoneNumber": ($exists(inputData.candidate.phoneNumbers) and $count(inputData.candidate.phoneNumbers) > 0) ? inputData.candidate.phoneNumbers[0].phoneNumber : "", 
            "city": $exists(inputData.candidate.address.city) ? inputData.candidate.address.city, 
            "state": $exists(inputData.candidate.address.state) ? inputData.candidate.address.state, 
            "postalCode": $exists(inputData.candidate.address.postalCode) ? inputData.candidate.address.postalCode, 
            "country": $exists(inputData.candidate.customFields.countryCode) ? inputData.candidate.customFields.countryCode 
        } 
    }, 
    "source": { 
        "submissionSource": "Joveo", 
        "submissionSourceName": ( 
            $medium := inputData.candidate.customFields.medium; 
            $interface := inputData.candidate.customFields.mediumInterface; 

            ($medium = "CONVERSATIONAL" and $interface = "WEB_CHATBOT") ? "Joveo Chatbot" : 
            ($medium = "CONVERSATIONAL" and $interface = "SMS") ? "Joveo SMS" : 
            ($medium = "CONVERSATIONAL" and $interface = "EMAIL") ? "Joveo Email" : 
            ($medium = "CONVERSATIONAL" and $interface = "WHATSAPP") ? "Joveo WhatsApp" : 
            ($medium = "FORM" and $interface = "WEB_CHATBOT") ? "Joveo Form" : 
            ($medium = "EASY_APPLY" and $interface = "WEB_CHATBOT") ? "Joveo Easy Apply" : 
            "Joveo Products" 
        ) 
    }, 
    "questions": ( 
        $getAnswerObjs := function($questions) { 
            ( 
                $questionIds := $keys($questions); 
                $map($questionIds, function($id) { 
                    ( 
                        $parts := $split($id, "_Question_"); 
                        $qId := $parts[0]; 
                        $qType := $count($parts) > 1 ? $parts[1] : "Prescreening"; 
                        { 
                            "type": $qType, 
                            "id": $qId, 
                            "response": $join([$lookup($questions, $id)], ",") 
                        } 
                    ) 
                }) 
            ) 
        }; 
        $questionAnswers := $exists(inputData.candidate.customFields.questionAnswers.additionalFields) ? inputData.candidate.customFields.questionAnswers.additionalFields : {}; 
        $getAnswerObjs($questionAnswers) 
    ), 
    "resume": ($exists(inputData.application.attachment) and inputData.application.attachment != null) ? { 
        "file": inputData.application.attachment.attachmentContent, 
        "fileName": inputData.application.attachment.attachmentFileName 
    } 
}

responseHandlers.jsonataConvertorExpression:
{
    "data": {"questions": {"additionalQuestions": [(
    $inputType:= function($responseType) {
        $responseType='Boolean' ? 'RADIO' : $responseType='MultipleChoiceMultipleAnswer' ? 'SELECT' : $responseType='MultipleChoiceSingleAnswer' ? 'SELECT' : $responseType='Text' ? 'TEXT' : $responseType='Numeric' ? 'TEXT' : $responseType='Date' ? 'DATE' : ''
        };

    $getScreeningQns := function() {
        (
            $data := cornerstone_get_application_wf[0].data;
            $questions := ($exists($data.actionItems) and $data.actionItems!=null and $count($data.actionItems) > 0) ? $data.actionItems : [];
            $filterByTypeQns := [$filter($questions, function($v, $i, $a) { $v.type='Compliance' or $v.type='Disclaimer' or $v.type='Prescreening'
                })
            ];
            [$filter($count($filterByTypeQns) > 0 ? $filterByTypeQns : [], function($v, $i, $a) { $v.responseType='Boolean' or $v.responseType='MultipleChoiceMultipleAnswer' or $v.responseType='MultipleChoiceSingleAnswer' or $v.responseType='Text' or $v.responseType='Numeric'  or $v.responseType='Date'
                })
            ]
        )
        };

    $isItMultiValQuestion := function($input) {
        $input = "MultipleChoiceMultipleAnswer" ? true : false
        };

    $inputOptionListObj := function($question) {
            [$map(($question.responseOptions=null or $count($question.responseOptions)=0) ? [] : $question.responseOptions, function($value) {
                    {
                        "label": $value.responseText,
                        "value": $value.responseId
                    }
                })
            ]
        };

    $inputValidationObj := function($question) {
        $question.responseType = "MultipleChoiceMultipleAnswer" ? {
                "maxSelections": $count($question.responseOptions)
            } : null
        };

    $dependencyCriteriaObj := function($question, $condition) {
        (
            $criterias := [
                {
                    "field": "additionalFields." & $condition.parentQuestionId & "_Question",
                    "values": $condition.responseId
                }
            ];

            {
                "criteria": $criterias,
                "operator": "ALL",
                "defaultBehavior": "SHOW"
            }
        )
        };

    $questionObj := function($question, $condition) {
        (
            $questionWithCondition := {
                "type": "QUESTION",
                "id": $question.id,
                "label": $question.questionText,
                "field": "additionalFields." & $question.id & "_Question_" & $question.type,
                "inputType": $inputType($question.responseType),
                "isMultiValue": $isItMultiValQuestion($question.responseType),
                "properties": {
                    "isMandatory": $question.required
                },
                "inputOptionList": $inputOptionListObj($question),
                "inputValidation": $inputValidationObj($question),
                "dependencyCriteria": $condition=null?null:$dependencyCriteriaObj($question, $condition)
            };

            $responses := ($exists($question.responseOptions) and $count($question.responseOptions) > 0)?$question.responseOptions: [];

            $branchQns := [$map($responses, function($response) {
                (
                    $conditionObj := {
                        "parentQuestionId": $question.id,
                        "responseId": $response.responseId
                    };

                    $branchQuestions := ($exists($response.branchedQuestions) and $count($response.branchedQuestions) > 0) ? $response.branchedQuestions : [];
                    [$map($branchQuestions, function($branchQuestion) {$questionObj($branchQuestion, $conditionObj)})] ~> $reduce($append)
                )
                })
            ] ~> $reduce($append);

            $append([$questionWithCondition], $branchQns)
        )
        };

    $questions := $getScreeningQns();
    [$map($questions, function($question) {$questionObj($question, null)})] ~> $reduce($append)

    )]}},
"errors": null
}
